/* Trig Integrals — renders window.TRIG (generated by build/build.py) into a searchable reference. */
(() => {
'use strict';
const DATA = window.TRIG;
const $ = (s, r = document) => r.querySelector(s);
const $$ = (s, r = document) => [...r.querySelectorAll(s)];
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const store = {
  get(k, d) { try { const v = localStorage.getItem(k); return v === null ? d : v; } catch (e) { return d; } },
  set(k, v) { try { localStorage.setItem(k, v); } catch (e) {} }
};

const METHODS = {
  usub: ['u-sub', 'u substitution u-sub chain rule'],
  parts: ['by parts', 'integration by parts tabular'],
  trigsub: ['trig sub', 'trigonometric substitution trig sub reference triangle'],
  identity: ['identity', 'identity double angle half angle power reducing product to sum'],
  reduction: ['reduction', 'reduction formula recursive recurrence'],
  weierstrass: ['t = tan(x/2)', 'weierstrass half angle tangent substitution universal'],
  partial: ['partial fractions', 'partial fractions'],
  'complete-square': ['complete the square', 'complete the square'],
  definite: ['definite', 'definite improper limits']
};
const FN_ORDER = ['sin', 'cos', 'tan', 'cot', 'sec', 'csc', 'arcsin', 'arccos', 'arctan', 'arccot', 'arcsec', 'arccsc',
  'sinh', 'cosh', 'tanh', 'coth', 'sech', 'csch', 'arsinh', 'arcosh', 'artanh'];
const GROUPS = [
  ['Start here', ['strategy', 'identities', 'derivatives']],
  ['Integrals', ['basic', 'powers', 'products', 'angles', 'rational', 'parts', 'inverse', 'trigsub', 'hyper', 'definite', 'special']],
  ['Practice', ['pdf']]
];
const NAMES = { strategy: 'Which method?', identities: 'Identities', derivatives: 'Derivatives' };
const SECTIONS = DATA.sections;
const byId = Object.fromEntries(SECTIONS.map(s => [s.id, s]));
const count = s => { const all = s.groups.reduce((n, g) => n + g.items.length, 0); const math = s.groups.reduce((n, g) => n + g.items.filter(i => i.k !== 'txt').length, 0); return math || all; };

/* ---------------- math typesetting (queued, lazy) ---------------- */
let mjReady = false, chain = Promise.resolve();
const typeset = el => { if (!mjReady) return; chain = chain.then(() => MathJax.typesetPromise([el])).catch(e => console.error(e)); };
const io = 'IntersectionObserver' in window ? new IntersectionObserver(es => {
  es.forEach(e => { if (e.isIntersecting) { io.unobserve(e.target); typeset(e.target); } });
}, { rootMargin: '700px 0px' }) : null;
const lazyTypeset = el => io ? io.observe(el) : typeset(el);

/* ---------------- rendering one item ---------------- */
const M = t => `\\(\\displaystyle ${esc(t)}\\)`;
const needsEq = r => !/^\\text\{/.test(r);
function latexOf(it) {
  if (it.k === 'i' || it.k === 'ne') return `${it.tex} = ${it.r} + C`;
  if (it.k === 'id' || it.k === 'red') return it.tex;
  if (it.k === 'no') return `${it.tex}:\\ ${it.r}`;
  return `${it.tex} = ${it.r}`;
}
function tagsHtml(it) {
  return (it.m || []).filter(m => METHODS[m]).map(m => `<span class="tag ${m}">${esc(METHODS[m][0])}</span>`).join('');
}
const REG = [];
function card(it) {
  const ref = REG.push(it) - 1;
  if (it.k === 'txt') {
    return `<article class="card k-txt fadein">${it.t ? `<span class="ttl">${esc(it.t)}</span>` : ''}<div class="eq0">${it.html}</div></article>`;
  }
  const wide = (it.tex.length + (it.r ? it.r.length : 0)) > 175 || it.k === 'red' ? ' wide' : '';
  let body = '';
  if (it.k === 'id' || it.k === 'red') {
    body = `<div class="eq prob">${M(it.tex)}</div>`;
  } else {
    let prob = it.tex, ans;
    if (it.k === 'der') prob = `\\frac{d}{dx}\\!\\left[${it.tex}\\right]`;
    if (it.k === 'i' || it.k === 'ne') ans = `= ${it.r}+C`;
    else if (it.k === 'no') ans = it.r;
    else ans = needsEq(it.r) ? `= ${it.r}` : it.r;
    body = `<div class="eq prob">${M(prob)}</div>
      <div class="ans"><div class="res">${M(ans)}</div><button class="rev" type="button">Show answer</button></div>`;
  }
  const extra = it.k === 'ne' ? '<span class="tag definite">special function</span>' : it.k === 'no' ? '<span class="tag partial">no closed form</span>' : '';
  const meta = [it.src ? `<span class="src">${it.src}</span>` : '', extra, tagsHtml(it), it.t ? `<span class="ttl">${it.t}</span>` : ''].join('');
  const note = it.note ? `<div class="note"><b>Note.</b> ${it.note}</div>` : '';
  return `<article class="card k-${it.k}${wide} fadein" data-ref="${ref}" data-fn="${(it.fn || []).join(' ')}" data-m="${(it.m || []).join(' ')}">
    <div class="meta">${meta}</div>${body}${note}
    <button class="copy" type="button" title="Copy LaTeX" aria-label="Copy LaTeX">⧉ TeX</button></article>`;
}

/* ---------------- search ---------------- */
const STOP = new Set(['integral', 'integrals', 'integrate', 'of', 'the', 'a', 'an', 'antiderivative', 'formula', 'for', 'int', 'dx']);
const SYN = { atan: 'arctan', asin: 'arcsin', acos: 'arccos', asec: 'arcsec', acsc: 'arccsc', acot: 'arccot', arctg: 'arctan', ln: 'ln', 'u-sub': 'u-sub' };
const SUP = { '²': '^2', '³': '^3', '⁴': '^4', '⁵': '^5', '⁶': '^6', '⁷': '^7', '⁸': '^8', 'ⁿ': '^n', 'π': 'pi', '√': 'sqrt', '∫': '' };
function norm(s) {
  s = String(s).toLowerCase();
  for (const k in SUP) s = s.split(k).join(SUP[k]);
  return s.replace(/\\(left|right|displaystyle|quad|text|operatorname|mathrm|dfrac|tfrac|frac|big|bigg|Big|Bigg|cdot|,|!|;|:| )/g, '')
    .replace(/[\\{}\s$()]/g, '');
}
const INDEX = [];
SECTIONS.forEach(sec => sec.groups.forEach(g => g.items.forEach(it => {
  if (it.k === 'txt') return;
  const mtxt = (it.m || []).map(m => METHODS[m] ? METHODS[m][1] : m).join(' ');
  INDEX.push({ it, sec, g,
    a: norm(it.tex), b: norm((it.r || '')),
    c: norm(`${it.t || ''} ${it.src || ''} ${it.kw || ''} ${g.t} ${sec.title}`) + ' ' + mtxt.toLowerCase().replace(/\s+/g, '') + ' ' + (it.m || []).join(' ') + ' ' + (it.fn || []).join(' '),
    words: (`${it.t || ''} ${it.src || ''} ${g.t} ${sec.title} ${mtxt}`).toLowerCase() });
})));
function search(q) {
  const toks = q.toLowerCase().split(/\s+/).filter(Boolean).map(t => SYN[t] || t).filter(t => !STOP.has(t));
  if (!toks.length) return [];
  const nt = toks.map(norm).filter(Boolean);
  const out = [];
  INDEX.forEach(e => {
    let score = 0, ok = true;
    for (let i = 0; i < nt.length; i++) {
      const t = nt[i];
      if (e.a.includes(t)) score += 3;
      else if (e.b.includes(t)) score += 2;
      else if (e.c.includes(t) || e.words.includes(toks[i])) score += 1;
      else { ok = false; break; }
    }
    if (ok) out.push([score + (e.a.length < 40 ? 0.5 : 0), e]);
  });
  out.sort((x, y) => y[0] - x[0]);
  return out.map(x => x[1]);
}

/* ---------------- views ---------------- */
const main = $('#main');
const state = { filters: {}, shown: 120 };
let current = 'home';

function setCurrent(id) {
  current = id;
  $$('#side a').forEach(a => a.setAttribute('aria-current', a.dataset.id === id ? 'page' : 'false'));
  document.body.classList.remove('nav-open');
  $('#menu').setAttribute('aria-expanded', 'false');
}
function mount(html) {
  io && io.disconnect();
  main.innerHTML = html;
  window.scrollTo(0, 0);
  $$('.card, .tile, h2, .lead, .gnote, .exlinks a, .lesson-card p', main).forEach(lazyTypeset);
}
function blurbShort(s) { return s.split(/\.\s/)[0].replace(/\.$/, '') + '.'; }

function homeView() {
  const total = DATA.meta.total;
  const tiles = SECTIONS.map(s => `<a class="tile" href="#${s.id}"><div class="h">${esc(NAMES[s.id] || s.title)}<span>${count(s)}</span></div><p>${blurbShort(s.blurb)}</p></a>`).join('');
  const tri = (cls, o, a, h, title, ex) => `<div class="tri3"><svg viewBox="0 0 150 105" aria-hidden="true">${cls}</svg>${title}<br>${ex}</div>`;
  const T1 = `<path class="l a" d="M18 88 H100"/><path class="l o" d="M100 88 V22"/><path class="l h" d="M18 88 L100 22"/><text x="52" y="102">√(a²−x²)</text><text x="106" y="58">x</text><text x="44" y="46">a</text>`;
  const T2 = `<path class="l a" d="M18 88 H100"/><path class="l o" d="M100 88 V22"/><path class="l h" d="M18 88 L100 22"/><text x="60" y="102">a</text><text x="106" y="58">x</text><text x="6" y="48">√(a²+x²)</text>`;
  const T3 = `<path class="l a" d="M18 88 H100"/><path class="l o" d="M100 88 V22"/><path class="l h" d="M18 88 L100 22"/><text x="60" y="102">a</text><text x="106" y="58">√(x²−a²)</text><text x="44" y="46">x</text>`;
  const exs = [
    ['Example 1 · Type I', '\\int_0^2\\sqrt{16-x^2}\\,dx'],
    ['Example 2 · Type I', '\\int_1^{\\sqrt2}\\frac{dx}{x^2\\sqrt{4-x^2}}'],
    ['Example 3 · Type II', '\\int_0^1\\frac{dx}{(x^2+4)^{3/2}}'],
    ['Example 4 · Type III', '\\int\\frac{\\sqrt{x^2-144}}{x}\\,dx'],
    ['Example 5 · factor first', '\\int\\frac{5\\,dx}{\\sqrt{25x^2-9}}'],
    ['Example 6 · complete the square', '\\int_1^2\\frac{dx}{\\sqrt{4x-x^2}}']
  ].map((e, i) => `<a href="motion.html#ex${i + 1}"><small>${e[0]}</small><span>\\(${e[1]}\\)</span></a>`).join('');
  return `<section class="hero pagehead"><div class="eyebrow">Calculus II · Integration techniques</div>
    <h1>Every trig integral, in one place.</h1>
    <p class="lead">Identities, powers, products, trig substitution, rational functions, by-parts, hyperbolics, definite and improper integrals, special functions, and your MATH 1400 problems. Search anything, or hide the answers and quiz yourself.</p>
    <div class="stats"><span class="stat"><b>${total}</b> formulas</span><span class="stat"><b>${SECTIONS.length}</b> sections</span><span class="stat">each one <b>checked numerically</b></span></div></section>
    <section class="lesson-card"><div><div class="eyebrow">Animated lesson</div><h2>Trig Substitution in Motion</h2>
      <p>Six worked examples, each in three phases: <b>substitute</b>, <b>integrate</b>, <b>come back to x</b>. Every symbol moves from one step to the next, so you can see where it goes.</p>
      <a class="go" href="motion.html">Open the lesson →</a></div>
      <div class="tris">${tri(T1, 0, 0, 0, '<b>Type I</b>', 'x = a sin θ')}${tri(T2, 0, 0, 0, '<b>Type II</b>', 'x = a tan θ')}${tri(T3, 0, 0, 0, '<b>Type III</b>', 'x = a sec θ')}</div></section>
    <div class="exlinks">${exs}</div>
    <h2>All sections</h2><div class="tiles">${tiles}</div>`;
}

function chipRow(label, items, kind, sid) {
  if (items.length < 2) return '';
  const on = state.filters[sid] || { fn: [], m: [] };
  return `<div class="chiprow"><span class="lab">${label}</span>${items.map(([k, n, nm]) =>
    `<button class="fchip" type="button" data-kind="${kind}" data-k="${k}" aria-pressed="${on[kind].includes(k)}">${esc(nm)}<span class="m">${n}</span></button>`).join('')}</div>`;
}
function sectionView(sec) {
  const fnc = {}, mc = {};
  sec.groups.forEach(g => g.items.forEach(i => { (i.fn || []).forEach(f => fnc[f] = (fnc[f] || 0) + 1); (i.m || []).forEach(m => mc[m] = (mc[m] || 0) + 1); }));
  const fns = FN_ORDER.filter(f => fnc[f]).map(f => [f, fnc[f], f]);
  const ms = Object.keys(METHODS).filter(m => mc[m]).map(m => [m, mc[m], METHODS[m][0]]);
  const groups = sec.groups.map((g, gi) => `<section class="grp${g.quiz ? ' quizgroup' : ''}"><h2>${g.t}</h2>${g.note ? `<p class="gnote">${g.note}</p>` : ''}
    <div class="grid${g.cols ? ' c' + g.cols : ''}">${g.items.map(card).join('')}</div></section>`).join('');
  return `<div class="pagehead"><div class="eyebrow">${count(sec)} formulas</div><h1>${esc(NAMES[sec.id] || sec.title)}</h1><p class="lead">${sec.blurb}</p></div>
    <div class="filters">${chipRow('Function', fns, 'fn', sec.id)}${chipRow('Method', ms, 'm', sec.id)}</div>${groups}`;
}
function applyFilters(sid) {
  const f = state.filters[sid] || { fn: [], m: [] };
  $$('.card', main).forEach(c => {
    if (c.classList.contains('k-txt')) return;
    const fn = (c.dataset.fn || '').split(' '), m = (c.dataset.m || '').split(' ');
    const ok = (!f.fn.length || f.fn.some(x => fn.includes(x))) && (!f.m.length || f.m.some(x => m.includes(x)));
    c.hidden = !ok;
  });
  $$('section.grp', main).forEach(s => { s.hidden = !$$('.card:not([hidden])', s).length; });
}

function searchView(q) {
  const res = search(q);
  const head = `<div class="pagehead"><div class="eyebrow">Search</div><h1>${res.length ? res.length + ' result' + (res.length > 1 ? 's' : '') : 'No results'} for “${esc(q)}”</h1>
    <p class="lead">${res.length ? 'Matches in the integrand first, then the answer, then titles and method names.' : 'Try a function and a power (<b>sec^3</b>), a shape (<b>x sin x</b>), or a technique (<b>by parts</b>, <b>wallis</b>, <b>reduction</b>).'}</p></div>`;
  if (!res.length) return head + '<div class="empty">Nothing matched. Try fewer words.</div>';
  const shown = res.slice(0, state.shown);
  let html = head + `<div class="grid">${shown.map(e => card(e.it).replace('<div class="meta">', `<div class="meta"><a class="src" href="#${e.sec.id}">${esc(NAMES[e.sec.id] || e.sec.title)}</a>`)).join('')}</div>`;
  if (res.length > shown.length) html += `<button class="more" id="more" type="button">Show ${Math.min(120, res.length - shown.length)} more</button>`;
  return html;
}

/* ---------------- routing ---------------- */
let searching = '';
function route() {
  const id = (location.hash || '#home').slice(1);
  if (searching) return;
  const sec = byId[id];
  if (id !== 'home' && !sec) { location.hash = '#home'; return; }
  setCurrent(id);
  document.title = (sec ? (NAMES[id] || sec.title) + ' · ' : '') + 'Trig Integrals';
  mount(sec ? sectionView(sec) : homeView());
  if (sec) applyFilters(id);
}
function runSearch(q) {
  searching = q.trim();
  if (!searching) { searching = ''; route(); return; }
  state.shown = 120;
  setCurrent('');
  document.title = 'Search · Trig Integrals';
  mount(searchView(searching));
}

/* ---------------- events ---------------- */
main.addEventListener('click', ev => {
  const t = ev.target;
  const chip = t.closest('.fchip');
  if (chip) {
    const f = state.filters[current] || (state.filters[current] = { fn: [], m: [] });
    const arr = f[chip.dataset.kind], k = chip.dataset.k;
    const i = arr.indexOf(k); i > -1 ? arr.splice(i, 1) : arr.push(k);
    chip.setAttribute('aria-pressed', i === -1);
    applyFilters(current);
    return;
  }
  const rev = t.closest('.rev');
  if (rev) { rev.closest('.card').classList.add('open'); return; }
  const cp = t.closest('.copy');
  if (cp) {
    const e = REG[+cp.closest('.card').dataset.ref];
    const text = e ? latexOf(e) : '';
    (navigator.clipboard ? navigator.clipboard.writeText(text) : Promise.reject()).then(() => flash(cp, '✓ copied'), () => flash(cp, 'copy failed'));
    return;
  }
  if (t.id === 'more') { state.shown += 120; mount(searchView(searching)); return; }
});
function flash(btn, msg) { const o = btn.textContent; btn.textContent = msg; btn.classList.add('done'); setTimeout(() => { btn.textContent = o; btn.classList.remove('done'); }, 1100); }
$('#q').addEventListener('input', (() => { let t; return e => { clearTimeout(t); t = setTimeout(() => runSearch(e.target.value), 140); }; })());
$('#q').addEventListener('keydown', e => { if (e.key === 'Escape') { e.target.value = ''; runSearch(''); e.target.blur(); } });
document.addEventListener('keydown', e => {
  if (e.key === '/' && !/input|textarea/i.test(document.activeElement.tagName)) { e.preventDefault(); $('#q').focus(); $('#q').select(); }
});
window.addEventListener('hashchange', () => { searching = ''; $('#q').value = ''; route(); });
$('#brand').addEventListener('click', () => { searching = ''; $('#q').value = ''; });
$('#menu').addEventListener('click', () => { const o = document.body.classList.toggle('nav-open'); $('#menu').setAttribute('aria-expanded', o); });
document.addEventListener('click', e => { if (document.body.classList.contains('nav-open') && !e.target.closest('#side') && !e.target.closest('#menu')) document.body.classList.remove('nav-open'); });

/* study mode + theme */
function setStudy(on) { document.body.classList.toggle('hide-ans', on); $('#study').setAttribute('aria-pressed', on); store.set('ti-study', on ? '1' : '0'); }
$('#study').addEventListener('click', () => setStudy(!document.body.classList.contains('hide-ans')));
function setTheme(t) { if (t) document.documentElement.dataset.theme = t; else delete document.documentElement.dataset.theme; }
const prefersDark = () => matchMedia('(prefers-color-scheme: dark)').matches;
$('#theme').addEventListener('click', () => {
  const cur = document.documentElement.dataset.theme || (prefersDark() ? 'dark' : 'light');
  const next = cur === 'dark' ? 'light' : 'dark'; setTheme(next); store.set('ti-theme', next);
});

/* ---------------- boot ---------------- */
function buildNav() {
  let h = `<a data-id="home" href="#home"><span>Overview</span></a>`;
  GROUPS.forEach(([label, ids]) => {
    h += `<div class="grp">${label}</div>` + ids.filter(i => byId[i]).map(i => `<a data-id="${i}" href="#${i}"><span>${esc(NAMES[i] || byId[i].title)}</span><span class="n">${count(byId[i])}</span></a>`).join('');
  });
  h += `<a class="lesson" data-id="lesson" href="motion.html"><span>Trig substitution, animated</span></a>`;
  $('#side').innerHTML = h;
  $('#foot').innerHTML = `<p>${DATA.meta.total} formulas. Every antiderivative was differentiated and every definite integral was integrated numerically (mpmath, 30 digits) before this page was generated. Built from <i>MATH 1400 Prep Quizzes &amp; Practice Problems</i> and <i>Trig Substitution in Motion</i>. Constants of integration are omitted unless shown; Type III formulas assume x&nbsp;&gt;&nbsp;a.</p>`;
}
const t0 = store.get('ti-theme', ''); if (t0) setTheme(t0);
buildNav();
if (store.get('ti-study', '0') === '1') setStudy(true);

let started = false;
function start() {
  if (started) return;
  const ready = window.MathJax && MathJax.startup && MathJax.startup.promise;
  if (!ready) { setTimeout(start, 60); return; }
  started = true;
  MathJax.startup.promise.then(() => document.fonts ? document.fonts.ready : null).then(() => { mjReady = true; route(); })
    .catch(err => { $('#loading') && ($('#loading').textContent = 'The math renderer failed to load. Check your connection and reload.'); console.error(err); });
}
// show structure immediately; math fills in as MathJax arrives
if (document.readyState === 'complete') start(); else window.addEventListener('load', start);
})();
